Copy the workbook, read the cached Cost, ITV, and Profit values for rows 3–6 from the active sheet. Apply the three-case rule: loss → ITV + Profit, profit below cost → Profit, otherwise Cost − ITV. Write the resulting plain numbers into H3:H6, leaving cell styles untouched.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def as_number(x):
    if x is None:
        return 0.0
    try:
        return float(x)
    except (TypeError, ValueError):
        return 0.0

for r in range(3, 7):
    cost = as_number(vws.cell(row=r, column=3).value)   # C
    itv = as_number(vws.cell(row=r, column=5).value)    # E
    profit = as_number(vws.cell(row=r, column=6).value) # F

    if profit < 0:
        result = itv + profit
    elif profit < cost:
        result = profit
    else:
        result = cost - itv

    result = round(result, 2)
    if result == int(result):
        result = int(result)

    ws.cell(row=r, column=8).value = result
    print(f"Row {r}: H={result}")

wb.save(OUT)
